package java.util;
import java.util.function.*;
public interface Comparator<T> { int compare(T a,T b); default Comparator<T> reversed(){final Comparator<T> self=this;return new Comparator<T>(){public int compare(T a,T b){return self.compare(b,a);}};} default Comparator<T> thenComparing(final Comparator<? super T> c){Objects.requireNonNull(c);final Comparator<T> self=this;return new Comparator<T>(){public int compare(T a,T b){int x=self.compare(a,b);return x!=0?x:c.compare(a,b);}};} default <U extends Comparable<? super U>> Comparator<T> thenComparing(Function<? super T,? extends U> f){return thenComparing(Comparator.<T,U>comparing(f));} default <U> Comparator<T> thenComparing(Function<? super T,? extends U> f,Comparator<? super U> c){return thenComparing(Comparator.<T,U>comparing(f,c));} default Comparator<T> thenComparingInt(ToIntFunction<? super T> f){return thenComparing(Comparator.<T>comparingInt(f));} default Comparator<T> thenComparingLong(ToLongFunction<? super T> f){return thenComparing(Comparator.<T>comparingLong(f));} default Comparator<T> thenComparingDouble(ToDoubleFunction<? super T> f){return thenComparing(Comparator.<T>comparingDouble(f));} static <T extends Comparable<? super T>> Comparator<T> naturalOrder(){return new Comparator<T>(){public int compare(T a,T b){return a.compareTo(b);}};} static <T extends Comparable<? super T>> Comparator<T> reverseOrder(){return new Comparator<T>(){public int compare(T a,T b){return b.compareTo(a);}};} static <T,U extends Comparable<? super U>> Comparator<T> comparing(final Function<? super T,? extends U> f){Objects.requireNonNull(f);return new Comparator<T>(){public int compare(T a,T b){return f.apply(a).compareTo(f.apply(b));}};} static <T,U> Comparator<T> comparing(final Function<? super T,? extends U> f,final Comparator<? super U> c){Objects.requireNonNull(f);Objects.requireNonNull(c);return new Comparator<T>(){public int compare(T a,T b){return c.compare(f.apply(a),f.apply(b));}};} static <T> Comparator<T> comparingInt(final ToIntFunction<? super T> f){Objects.requireNonNull(f);return new Comparator<T>(){public int compare(T a,T b){return Integer.compare(f.applyAsInt(a),f.applyAsInt(b));}};} static <T> Comparator<T> comparingLong(final ToLongFunction<? super T> f){Objects.requireNonNull(f);return new Comparator<T>(){public int compare(T a,T b){return Long.compare(f.applyAsLong(a),f.applyAsLong(b));}};} static <T> Comparator<T> comparingDouble(final ToDoubleFunction<? super T> f){Objects.requireNonNull(f);return new Comparator<T>(){public int compare(T a,T b){return Double.compare(f.applyAsDouble(a),f.applyAsDouble(b));}};} static <T> Comparator<T> nullsFirst(final Comparator<? super T> c){return new Comparator<T>(){public int compare(T a,T b){return a==null?(b==null?0:-1):b==null?1:c==null?0:c.compare(a,b);}};} static <T> Comparator<T> nullsLast(final Comparator<? super T> c){return new Comparator<T>(){public int compare(T a,T b){return a==null?(b==null?0:1):b==null?-1:c==null?0:c.compare(a,b);}};} }
